div.t-attf-class:
progress-fill {{
                                                    'progress-green' if (o.porcentaje_produccion_total or 0.0) >= 100 else
                                                    'progress-blue' if (o.porcentaje_produccion_total or 0.0) >= 95 else
                                                    'progress-orange' if (o.porcentaje_produccion_total or 0.0) >= 80 else
                                                    'progress-red'
                                                }}
